/*
We model the labyrinth as states (floor, r, c).

Input format is not explicitly given in the prompt, so this solution assumes the
common format for this problem type:

n m
<floor 0 map: n lines>
<floor 1 map: n lines>

Characters:
'#' : wall
'.' : empty cell
'S' : start
'E' : exit
'X' : switch cell (can move to the same position on the other floor)
Other non-wall cells are treated as walkable.

Movement:
- 4-directional move on the same floor, cost 1
- If current cell is 'X', may switch to the other floor at same (r,c), cost 1

Output:
minimum steps from S to E, or -1 if impossible.

If the judge uses different symbols but same idea, adapt the symbol checks below.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<string> g[2];
    g[0].resize(n);
    g[1].resize(n);

    for (int i = 0; i < n; ++i) cin >> g[0][i];
    for (int i = 0; i < n; ++i) cin >> g[1][i];

    auto inside = [&](int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    };

    auto wall = [&](char ch) {
        return ch == '#';
    };

    int sf = -1, sr = -1, sc = -1;
    vector<tuple<int,int,int>> exits;

    for (int f = 0; f < 2; ++f) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (g[f][i][j] == 'S') {
                    sf = f; sr = i; sc = j;
                }
                if (g[f][i][j] == 'E') {
                    exits.push_back({f, i, j});
                }
            }
        }
    }

    if (sf == -1) {
        cout << -1 << '\n';
        return 0;
    }

    const int INF = 1e9;
    vector<vector<vector<int>>> dist(2, vector<vector<int>>(n, vector<int>(m, INF)));
    queue<tuple<int,int,int>> q;

    dist[sf][sr][sc] = 0;
    q.push({sf, sr, sc});

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    while (!q.empty()) {
        auto [f, r, c] = q.front();
        q.pop();

        int d = dist[f][r][c];
        if (g[f][r][c] == 'E') {
            cout << d << '\n';
            return 0;
        }

        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (!inside(nr, nc)) continue;
            if (wall(g[f][nr][nc])) continue;
            if (dist[f][nr][nc] > d + 1) {
                dist[f][nr][nc] = d + 1;
                q.push({f, nr, nc});
            }
        }

        if (g[f][r][c] == 'X') {
            int nf = 1 - f;
            if (!wall(g[nf][r][c]) && dist[nf][r][c] > d + 1) {
                dist[nf][r][c] = d + 1;
                q.push({nf, r, c});
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}

