#define MAX_N 100
#define MAX_M 100

typedef struct {
    int x, y, floor, dist;
} State;

int bfs(char map[2][MAX_N][MAX_M], int n, int m, int sx, int sy, int ex, int ey) {
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    int visited[2][MAX_N][MAX_M] = {0};

    State queue[2 * MAX_N * MAX_M];
    int front = 0, rear = 0;

    queue[rear].x = sx;
    queue[rear].y = sy;
    queue[rear].floor = 0;
    queue[rear].dist = 0;
    rear++;
    visited[0][sx][sy] = 1;

    while (front < rear) {
        State cur = queue[front++];
        int x = cur.x, y = cur.y, floor = cur.floor, dist = cur.dist;

        if (x == ex && y == ey && floor == 0) {
            return dist;
        }

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m && map[floor][nx][ny] != '#') {
                if (!visited[floor][nx][ny]) {
                    visited[floor][nx][ny] = 1;
                    queue[rear].x = nx;
                    queue[rear].y = ny;
                    queue[rear].floor = floor;
                    queue[rear].dist = dist + 1;
                    rear++;
                }
            }
        }

        if (map[floor][x][y] == 'S') {
            int other_floor = 1 - floor;
            if (!visited[other_floor][x][y] && map[other_floor][x][y] != '#') {
                visited[other_floor][x][y] = 1;
                queue[rear].x = x;
                queue[rear].y = y;
                queue[rear].floor = other_floor;
                queue[rear].dist = dist + 1;
                rear++;
            }
        }
    }

    return -1;
}

