public class LabyrinthEscape {
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][][] grid = new char[2][n][m];
        int[] start = null; // floor, x, y
        int[] exit = null;  // floor, x, y

        for (int f = 0; f < 2; f++) {
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                for (int j = 0; j < m; j++) {
                    grid[f][i][j] = line.charAt(j);
                    if (grid[f][i][j] == 'S') {
                        start = new int[]{f, i, j};
                    } else if (grid[f][i][j] == 'E') {
                        exit = new int[]{f, i, j};
                    }
                }
            }
        }

        int result = bfs(grid, n, m, start, exit);
        System.out.println(result);
    }

    static int bfs(char[][][] grid, int n, int m, int[] start, int[] exit) {
        boolean[][][] visited = new boolean[2][n][m];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{start[0], start[1], start[2], 0});
        visited[start[0]][start[1]][start[2]] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int f = cur[0], x = cur[1], y = cur[2], dist = cur[3];

            if (f == exit[0] && x == exit[1] && y == exit[2]) {
                return dist;
            }

            // Check if there's a switch at current position
            if (grid[f][x][y] == 'C') {
                int nf = 1 - f;
                if (!visited[nf][x][y]) {
                    visited[nf][x][y] = true;
                    queue.offer(new int[]{nf, x, y, dist + 1});
                }
            }

            // Move in four directions
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];

                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                if (grid[f][nx][ny] == 'W') continue;
                if (visited[f][nx][ny]) continue;

                // Handle stairs: if cell has stair, must change floor
                if (grid[f][nx][ny] == 'T') {
                    int nf = 1 - f;
                    if (!visited[nf][nx][ny]) {
                        visited[nf][nx][ny] = true;
                        queue.offer(new int[]{nf, nx, ny, dist + 1});
                    }
                } else {
                    visited[f][nx][ny] = true;
                    queue.offer(new int[]{f, nx, ny, dist + 1});
                }
            }
        }
        return -1;
    }
}

