/*
 * Two-floor labyrinth shortest path.
 *
 * Since the statement provided here is abbreviated, this solution implements the
 * standard model for a 2-floor maze with stairs / switches:
 *
 * - Input:
 *   n m
 *   n lines of floor 0
 *   n lines of floor 1
 *
 * Characters:
 *   '#' : wall
 *   '.' : empty cell
 *   'S' : start
 *   'E' : exit
 *   'U' : stair/switch cell allowing movement to the same (r,c) on the other floor
 *
 * Movement:
 *   - 4-directional movement on the same floor to non-wall cells, cost 1
 *   - If current cell is 'U', you may move to the same position on the other floor
 *     if that cell is not a wall, cost 1
 *
 * Output:
 *   Minimum number of steps from S to E, or -1 if unreachable.
 *
 * This is solved with BFS on states (floor, row, col).
 *
 * If your original judge uses different symbols for stairs/switches, only the
 * character checks in canSwitch(...) need adjustment.
 */
public class Main {
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class State {
        int f, r, c;
        State(int f, int r, int c) {
            this.f = f;
            this.r = r;
            this.c = c;
        }
    }

    static int n, m;
    static char[][][] g = new char[2][][];

    static boolean inBounds(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    static boolean passable(int f, int r, int c) {
        return g[f][r][c] != '#';
    }

    static boolean canSwitch(char ch) {
        return ch == 'U';
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) {
            System.out.println(-1);
            return;
        }
        n = Integer.parseInt(first);
        m = fs.nextInt();

        g[0] = new char[n][m];
        g[1] = new char[n][m];

        int sf = -1, sr = -1, sc = -1;
        int ef = -1, er = -1, ec = -1;

        for (int f = 0; f < 2; f++) {
            for (int i = 0; i < n; i++) {
                String s = fs.next();
                while (s != null && s.length() < m) {
                    String t = fs.next();
                    if (t == null) break;
                    s += t;
                }
                if (s == null || s.length() != m) {
                    System.out.println(-1);
                    return;
                }
                for (int j = 0; j < m; j++) {
                    g[f][i][j] = s.charAt(j);
                    if (g[f][i][j] == 'S') {
                        sf = f; sr = i; sc = j;
                    } else if (g[f][i][j] == 'E') {
                        ef = f; er = i; ec = j;
                    }
                }
            }
        }

        if (sf == -1 || ef == -1) {
            System.out.println(-1);
            return;
        }

        int[][][] dist = new int[2][n][m];
        for (int f = 0; f < 2; f++) {
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[f][i], -1);
            }
        }

        ArrayDeque<State> q = new ArrayDeque<>();
        dist[sf][sr][sc] = 0;
        q.offer(new State(sf, sr, sc));

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!q.isEmpty()) {
            State cur = q.poll();
            int d = dist[cur.f][cur.r][cur.c];

            if (cur.f == ef && cur.r == er && cur.c == ec) {
                System.out.println(d);
                return;
            }

            for (int k = 0; k < 4; k++) {
                int nr = cur.r + dr[k];
                int nc = cur.c + dc[k];
                if (!inBounds(nr, nc)) continue;
                if (!passable(cur.f, nr, nc)) continue;
                if (dist[cur.f][nr][nc] == -1) {
                    dist[cur.f][nr][nc] = d + 1;
                    q.offer(new State(cur.f, nr, nc));
                }
            }

            if (canSwitch(g[cur.f][cur.r][cur.c])) {
                int nf = 1 - cur.f;
                if (passable(nf, cur.r, cur.c) && dist[nf][cur.r][cur.c] == -1) {
                    dist[nf][cur.r][cur.c] = d + 1;
                    q.offer(new State(nf, cur.r, cur.c));
                }
            }
        }

        System.out.println(-1);
    }
}

from collections import deque
import sys

def solve():
    input_data = sys.stdin.read().split('\n')
    idx = 0

    while idx < len(input_data):
        line = input_data[idx].strip()
        idx += 1
        if not line:
            continue

        parts = line.split()
        if len(parts) < 2:
            continue

        R, C = int(parts[0]), int(parts[1])

        floors = []
        for f in range(2):
            grid = []
            for r in range(R):
                while idx < len(input_data) and input_data[idx].strip() == '':
                    idx += 1
                if idx < len(input_data):
                    grid.append(input_data[idx].strip())
                    idx += 1
            floors.append(grid)

        # Find start and goal
        start = None
        goal = None

        for f in range(2):
            for r in range(R):
                for c in range(len(floors[f][r])):
                    ch = floors[f][r][c]
                    if ch == 'S':
                        start = (f, r, c)
                    elif ch == 'G':
                        goal = (f, r, c)

        if start is None or goal is None:
            print(-1)
            continue

        # BFS
        dist = {}
        dist[start] = 0
        q = deque([start])

        dirs = [(0,1),(0,-1),(1,0),(-1,0)]

        found = False
        while q:
            f, r, c = q.popleft()
            d = dist[(f, r, c)]

            if (f, r, c) == goal:
                print(d)
                found = True
                break

            ch = floors[f][r][c]

            # Try moving on same floor
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    nch = floors[f][nr][nc]
                    if nch != '#':
                        state = (f, nr, nc)
                        if state not in dist:
                            dist[state] = d + 1
                            q.append(state)

            # Try switching floors via stairs
            if ch == '%':
                nf = 1 - f
                if 0 <= r < R and 0 <= c < C:
                    nch = floors[nf][r][c]
                    if nch == '%':
                        state = (nf, r, c)
                        if state not in dist:
                            dist[state] = d + 1
                            q.append(state)

        if not found:
            print(-1)

